package main

import (
 "crypto/sha256"
 "encoding/hex"
 "encoding/json"
 "fmt"
 "os"
 "github.com/SalehAlobaylan/c4isr-systems/internal/reference"
 "github.com/SalehAlobaylan/c4isr-systems/internal/simulation"
 "github.com/SalehAlobaylan/c4isr-systems/internal/simscene"
 "github.com/SalehAlobaylan/c4isr-systems/internal/contextpackage"
)
func main(){
 height:=10.0
 frame:=simulation.DefaultFrame(simulation.Position{Longitude:39.2,Latitude:21.5,Height:&height,VerticalDatum:"WGS84_ELLIPSOID"})
 out:=[]map[string]any{}
 for _,name:=range []string{"elevation","places"}{
  path:="testdata/reference/jeddah-makkah/"+name+".json"
  raw,e:=os.ReadFile(path);if e!=nil{panic(e)}
  var input reference.Input;if e=json.Unmarshal(raw,&input);e!=nil{panic(e)}
  sum:=sha256.Sum256(input.Artifact);hash:=hex.EncodeToString(sum[:])
  b:=contextpackage.Bundle{Manifest:contextpackage.Manifest{Assets:[]contextpackage.Asset{{Kind:input.Kind,SHA256:hash,VerticalDatum:input.VerticalDatum,DatasetID:name}}},Assets:map[string][]byte{hash:input.Artifact}}
  g,e:=simscene.GeometryFor(b,frame)
  result:=map[string]any{"file":path,"artifactHashMatches":hash==input.SHA256,"verticalDatum":input.VerticalDatum,"loaderSucceeded":e==nil,"partialTerrainSamples":len(g.Terrain),"partialReferencePoints":len(g.Points)}
  if e!=nil{result["error"]=e.Error()}
  out=append(out,result)
 }
 data,_:=json.MarshalIndent(out,"","  ");fmt.Println(string(data))
}
